<template>
  <div class="space-y-4">
    <div class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
      <h1 class="text-xl font-bold text-navy">Audit log</h1>
      <div class="grid grid-cols-1 gap-2 sm:grid-cols-2">
        <label class="min-w-0 space-y-1">
          <span class="block text-xs font-semibold text-muted">Date range</span>
          <DateRangePicker v-model="dateRange" />
        </label>
        <label class="min-w-0 space-y-1">
          <span class="block text-xs font-semibold text-muted">Action</span>
          <SearchSelect v-model="actionFilter" :options="actionOptions" aria-label="Filter audit actions" class="w-full sm:w-56" />
        </label>
      </div>
    </div>

    <div v-if="loading" class="text-sm text-muted">Loading…</div>
    <div v-else-if="err" class="text-sm text-expense">{{ err }}</div>
    <ul v-else class="bg-white rounded-xl border border-border divide-y divide-border">
      <li v-for="a in items" :key="a.id" class="p-3 text-sm">
        <div class="flex justify-between gap-2">
          <span class="font-mono text-xs text-primary">{{ a.action }}</span>
          <span
            class="text-[10px] uppercase font-semibold"
            :class="a.outcome === 'success' ? 'text-income' : 'text-expense'"
          >{{ a.outcome }}</span>
        </div>
        <div class="text-xs text-muted mt-0.5">
          {{ formatTime(a.created_at) }}
          <span v-if="a.actor_email"> · {{ a.actor_email }}</span>
          <span v-if="a.ip_address"> · {{ a.ip_address }}</span>
        </div>
        <div v-if="a.entity_type" class="text-xs text-muted">
          {{ a.entity_type }} {{ a.entity_id ? `#${a.entity_id.slice(0, 8)}` : '' }}
        </div>
      </li>
      <li v-if="!items.length" class="p-6 text-center text-sm text-muted">No audit events</li>
    </ul>
    <p class="text-xs text-muted">Showing {{ items.length }} of {{ total }}</p>
  </div>
</template>

<script setup lang="ts">
import type { AuditEntry } from '~/types/api'
import { currentMonthRange } from '~/utils/dateRanges'

const { api } = useApi()
const items = ref<AuditEntry[]>([])
const total = ref(0)
const loading = ref(true)
const err = ref('')
const actionFilter = ref('')
const dateRange = ref(currentMonthRange())
const actionOptions = [
  { value: '', label: 'All actions' },
  { value: 'auth.login', label: 'Login' },
  { value: 'auth.login_failed', label: 'Login failed' },
  { value: 'transaction.create', label: 'Transaction created' },
  { value: 'transaction.void', label: 'Transaction voided' },
  { value: 'transaction.approve', label: 'Transaction approved' },
  { value: 'transaction.reverse', label: 'Transaction reversed' },
  { value: 'report.export', label: 'Report export' },
  { value: 'settings.change', label: 'Settings change' },
]

function formatTime(d: string) {
  try {
    return new Date(d).toLocaleString('en-GB', { dateStyle: 'short', timeStyle: 'medium' })
  } catch {
    return d
  }
}

async function load() {
  loading.value = true
  err.value = ''
  try {
    const res = await api<{ items: AuditEntry[]; total: number }>('/audit-logs', {
      query: {
        action: actionFilter.value || undefined,
        date_from: dateRange.value.from || undefined,
        date_to: dateRange.value.to || undefined,
        page_size: 50,
      },
    })
    items.value = res.items || []
    total.value = res.total || 0
  } catch (e: any) {
    err.value = e?.data?.error || 'Failed to load audit log'
  } finally {
    loading.value = false
  }
}

watch(() => [actionFilter.value, dateRange.value.from, dateRange.value.to], () => { void load() })

onMounted(load)
</script>
